import os, socket
# Check environment and host resolution
print("HOSTNAME:", socket.gethostname())
try:
    print("DB_HOST env:", os.environ.get('TESTVDB_DB_URL'))
    print("PGHOST env:", os.environ.get('PGHOST'))
except:
    pass
# Try to resolve common names
for host in ['localhost', '127.0.0.1', 'postgres', 'testvdb-db']:
    try:
        ip = socket.gethostbyname(host)
        print(f"{host} resolves to {ip}")
    except:
        print(f"{host} does NOT resolve")

import os, socket, subprocess

# Check all env vars
for k, v in sorted(os.environ.items()):
    if 'DB' in k.upper() or 'PG' in k.upper() or 'HOST' in k.upper() or 'PORT' in k.upper() or 'POSTGRES' in k.upper():
        print(f"{k}={v}")

# Check if postgres is running locally
print("\n--- Checking processes ---")
try:
    result = subprocess.run(['ps', 'aux'], capture_output=True, text=True, timeout=2)
    print(result.stdout)
except:
    print("ps aux failed")

# Check network
print("\n--- Checking network ---")
try:
    result = subprocess.run(['ip', 'addr'], capture_output=True, text=True, timeout=2)
    print(result.stdout)
except:
    print("ip addr failed")

# Check /etc/hosts
print("\n--- /etc/hosts ---")
try:
    with open('/etc/hosts') as f:
        print(f.read())
except:
    print("failed")

# Check /etc/resolv.conf
print("\n--- resolv.conf ---")
try:
    with open('/etc/resolv.conf') as f:
        print(f.read())
except:
    print("failed")
